<?php
/** Isolated SELECT-only source routing contracts; no DB, credentials or network. */
$root = getenv('SCHOOLSAFE_CONTRACT_PHP_ROOT') ?: dirname(__DIR__).'/app/modules/codex-ui-v1/extensions-test-runtime';
require_once $root.'/schoolsafe-attendance/ArrivalRead.php';
$passed=0;$failed=0;
function expectArrival($condition,$message='arrival availability assertion') { if (!$condition) throw new RuntimeException($message); }
function arrivalCase($name,$test) { global $passed,$failed; try {$test();++$passed;echo "PASS $name\n";} catch(Throwable $e) {++$failed;echo "FAIL $name: ".$e->getMessage()."\n";} }
function arrivalProbe($bridge,$native,&$calls) { return static function($sql) use($bridge,$native,&$calls) {
    $calls[]=$sql;
    if (preg_match("/to_regclass\\('([^']+)'\\)/",$sql,$m)) return [['t'=>($m[1]==='schoolsafe_attendance.arrival_ledger'?$bridge:$native)?$m[1]:null]];
    if (strpos($sql,'information_schema.columns')!==false) return [['n'=>5]];
    throw new RuntimeException('UNEXPECTED_DATA_QUERY');
}; }
function expectUnavailableArrival($test) { try {$test();} catch(RuntimeException $e) {expectArrival($e->getMessage()==='ARRIVAL_READ_UNAVAILABLE');return;} throw new RuntimeException('Expected explicit unavailable source, not SQL or an invented zero'); }
$admin=['profile'=>'admin','staff'=>'7','school'=>'2','year'=>'2026'];$filters=['date'=>'2026-10-23'];
arrivalCase('missing sources fail before executing any unavailable-table SQL',function()use($admin,$filters){$calls=[];$probe=arrivalProbe(false,false,$calls);expectUnavailableArrival(fn()=>SchoolSafeArrivalReadScope($admin,$filters,$probe));expectArrival(count($calls)===2);foreach($calls as $sql)expectArrival(strpos($sql,'SELECT to_regclass(')===0);});
arrivalCase('native-only source never refers to absent bridge',function()use($admin,$filters){$calls=[];$r=SchoolSafeArrivalReadScope($admin,$filters,arrivalProbe(false,true,$calls));expectArrival(strpos($r['from'],'entry_exit_student_records')!==false);expectArrival(strpos($r['from'],'arrival_ledger')===false);});
arrivalCase('bridge-only source never refers to absent native module',function()use($admin,$filters){$calls=[];$r=SchoolSafeArrivalReadScope($admin,$filters,arrivalProbe(true,false,$calls));expectArrival(strpos($r['from'],'arrival_ledger')!==false);expectArrival(strpos($r['from'],'entry_exit_student_records')===false);});
arrivalCase('both present sources retain union and valid-enrollment evidence',function()use($admin,$filters){$calls=[];$r=SchoolSafeArrivalReadScope($admin,$filters,arrivalProbe(true,true,$calls));expectArrival(strpos($r['from'],'UNION ALL')!==false);expectArrival(strpos($r['from'],'e.id=l.enrollment_id')!==false);expectArrival(strpos($r['from'],"r.unauthorized IS NULL")!==false);});
arrivalCase('school year date evidence and enrollment scope stay enforced',function()use($admin,$filters){$calls=[];$r=SchoolSafeArrivalReadScope($admin,$filters,arrivalProbe(false,true,$calls));foreach(['l.school_id=2','l.syear=2026',"l.school_date='2026-10-23'","l.status='arrival_evidence'",'e.start_date<=l.school_date','e.end_date>=l.school_date']as$clause)expectArrival(strpos($r['where'],$clause)!==false);});
arrivalCase('failed capability probes cannot fall through into raw DB execution',function()use($admin,$filters){expectUnavailableArrival(fn()=>SchoolSafeArrivalReadScope($admin,$filters,static function(){throw new RuntimeException('PROBE_FAILED');}));});
arrivalCase('malformed context is rejected before source or data queries',function()use($admin,$filters){try{SchoolSafeArrivalReadScope(array_replace($admin,['school'=>'2 OR 1=1']),$filters,static function(){throw new RuntimeException('UNEXPECTED_QUERY');});}catch(InvalidArgumentException $e){expectArrival($e->getMessage()==='INVALID_ARRIVAL_SCOPE');return;}throw new RuntimeException('Expected scope refusal');});
arrivalCase('invalid filter is rejected before probing capabilities',function()use($admin){try{SchoolSafeArrivalReadScope($admin,['date'=>'2026-02-30'],static function(){throw new RuntimeException('UNEXPECTED_QUERY');});}catch(InvalidArgumentException $e){expectArrival($e->getMessage()==='INVALID_ARRIVAL_DATE');return;}throw new RuntimeException('Expected date refusal');});
arrivalCase('teacher assignment is still reauthorized before evidence access',function()use($admin,$filters){$calls=[];$probe=arrivalProbe(false,true,$calls);try{SchoolSafeArrivalReadScope(array_replace($admin,['profile'=>'teacher']),$filters+['course_period_id'=>'9'],static function($sql)use($probe){return strpos($sql,'SELECT to_regclass(')===0||strpos($sql,'information_schema.columns')!==false?$probe($sql):[];});}catch(RuntimeException $e){expectArrival($e->getMessage()==='ARRIVAL_ACCESS_DENIED');return;}throw new RuntimeException('Expected teacher assignment refusal');});
arrivalCase('a present empty source is genuine zero, not unavailable',function()use($admin,$filters){$calls=[];$probe=arrivalProbe(false,true,$calls);$r=SchoolSafeArrivalRead($admin,$filters,static function($sql)use($probe){if(strpos($sql,'SELECT to_regclass(')===0||strpos($sql,'information_schema.columns')!==false)return$probe($sql);return strpos($sql,'SELECT count(DISTINCT')===0?[['students'=>'0','events'=>'0']]:[];});expectArrival($r['summary']['events']==='0'&&$r['rows']===[]);});
arrivalCase('public regclass unqualified PostgreSQL output is accepted',function(){expectArrival(SchoolSafeArrivalTableReady(static fn()=>[['t'=>'entry_exit_student_records']],'public.entry_exit_student_records'));});
arrivalCase('wrong schema never masquerades as public native table',function(){expectArrival(!SchoolSafeArrivalTableReady(static fn()=>[['t'=>'foreign.entry_exit_student_records']],'public.entry_exit_student_records'));});
arrivalCase('incomplete scope never attempts native data SQL',function()use($admin,$filters){expectUnavailableArrival(fn()=>SchoolSafeArrivalReadScope($admin,$filters,static function($sql){if(strpos($sql,'information_schema.columns')!==false)return[['n'=>4]];return [['t'=>strpos($sql,'public.entry_exit_student_records')!==false?'entry_exit_student_records':null]];}));});
arrivalCase('record scope not enrollment determines native tenant',function()use($admin,$filters){$calls=[];$r=SchoolSafeArrivalReadScope($admin,$filters,arrivalProbe(false,true,$calls));foreach(['r.schoolsafe_scan_school_id AS school_id','r.schoolsafe_scan_syear AS syear','e.school_id=r.schoolsafe_scan_school_id','e.syear=r.schoolsafe_scan_syear']as$clause)expectArrival(strpos($r['from'],$clause)!==false);});
echo json_encode(['passed'=>$passed,'failed'=>$failed])."\n";exit($failed?1:0);
